```cpp
#include <array>
#include <cstddef>
#include <vector>
#include <omp.h>

using std::size_t;

void pixelCounts(std::vector<int> const& image, std::array<size_t, 256> &bins) {
    bins.fill(0);

    #pragma omp parallel
    {
        std::array<size_t, 256> local_bins{};

        #pragma omp for nowait
        for (size_t i = 0; i < image.size(); ++i) {
            const int value = image[i];
            if (value >= 0 && value < 256) {
                ++local_bins[static_cast<size_t>(value)];
            }
        }

        #pragma omp critical
        {
            for (size_t bin = 0; bin < 256; ++bin) {
                bins[bin] += local_bins[bin];
            }
        }
    }
}
